-- Supabase Dashboard > SQL Editor 에서 전체 실행

create table if not exists public.question_sets (
  id bigint generated by default as identity primary key,
  title text not null, year int, subject text,
  answer_status text not null default '가답안',
  created_at timestamptz not null default now()
);

create table if not exists public.questions (
  id bigint generated by default as identity primary key,
  set_id bigint not null references public.question_sets(id) on delete cascade,
  question_no int not null, stem text not null, choices jsonb not null,
  correct_answer int not null check (correct_answer between 1 and 4),
  major_category text, mid_category text, topic text, explanation text,
  review_status text not null default '검수대기',
  created_at timestamptz not null default now(),
  unique(set_id, question_no)
);

create table if not exists public.user_question_state (
  user_id uuid not null references auth.users(id) on delete cascade,
  question_id bigint not null references public.questions(id) on delete cascade,
  selected_answer int check (selected_answer between 1 and 4),
  confidence text check (confidence in ('확실','애매','모름')),
  personal_note text, updated_at timestamptz not null default now(),
  primary key(user_id, question_id)
);

create table if not exists public.user_set_progress (
  user_id uuid not null references auth.users(id) on delete cascade,
  set_id bigint not null references public.question_sets(id) on delete cascade,
  submitted_at timestamptz, updated_at timestamptz not null default now(),
  primary key(user_id, set_id)
);

alter table public.question_sets enable row level security;
alter table public.questions enable row level security;
alter table public.user_question_state enable row level security;
alter table public.user_set_progress enable row level security;

drop policy if exists question_sets_read on public.question_sets;
create policy question_sets_read on public.question_sets for select to authenticated using (true);
drop policy if exists questions_read on public.questions;
create policy questions_read on public.questions for select to authenticated using (true);
drop policy if exists own_question_state_all on public.user_question_state;
create policy own_question_state_all on public.user_question_state for all to authenticated using (auth.uid()=user_id) with check (auth.uid()=user_id);
drop policy if exists own_progress_all on public.user_set_progress;
create policy own_progress_all on public.user_set_progress for all to authenticated using (auth.uid()=user_id) with check (auth.uid()=user_id);

insert into public.question_sets(id,title,year,subject,answer_status)
values (1,'2026년도 국가공무원 7급 공개경쟁채용 제2차시험',2026,'경영학','가답안')
on conflict(id) do update set title=excluded.title,year=excluded.year,subject=excluded.subject,answer_status=excluded.answer_status;

insert into public.questions(set_id,question_no,stem,choices,correct_answer,major_category,mid_category,topic,explanation,review_status) values
(1, 1, '경영자 보상에 대한 설명으로 옳지 않은 것은?', '["스톡옵션은 자사주식을 약정된 가격으로 일정한 수량을 일정 기간 내에 매입할 수 있는 권리이다.", "기업의 성과와 경영자의 이익이 일치할 수 있도록 설계한다.", "스톡옵션은 경영자가 기업의 장기성과에 집중하게 하는 특성이 있다.", "경영자가 기업가치를 극대화할 수 있도록 한다."]'::jsonb, 3, '인적자원관리', '보상관리', '경영자 보상·스톡옵션', '스톡옵션은 주가와 연계된 장기 인센티브지만, 경영자가 반드시 장기성과에만 집중하도록 만드는 것은 아니다. 단기적인 주가 부양이나 위험선호를 유발할 수도 있어 ③이 부적절하다.', '검수대기'),
(1, 2, '특허로 제품이 보호되거나 경쟁자의 진입이 용이하지 않을 때 사용하는 가격전략은?', '["초기고가전략(skimming pricing)", "시장침투가격전략(penetration pricing)", "단수가격전략(odd pricing)", "2부제 가격전략(two-part pricing)"]'::jsonb, 1, '마케팅', '가격관리', '초기고가전략', '특허 등으로 경쟁이 제한되고 초기 구매자의 지불의사가 높을 때 높은 가격부터 시작해 점차 낮추는 초기고가전략을 사용할 수 있다.', '검수대기'),
(1, 3, '기업의 성장 전략에 대한 설명으로 옳지 않은 것은?', '["시장침투는 기존 시장에 기존 제품을 활용하여 더 많은 판매를 이끌어내는 전략이다.", "수직적 통합은 경쟁 기업을 인수ㆍ합병하여 자사 내에 통합하는 전략이며, 기업 규모의 확대를 최우선적인 목표로 한다.", "시장개발은 기존 제품을 판매할 수 있는 새로운 시장을 개척하여 판매를 증가시키는 전략이다.", "다각화는 새로운 사업 영역으로 확장하는 전략이며, 현재의 사업 영역과 관련되지 않는 영역으로 진출하기도 한다."]'::jsonb, 2, '경영전략', '성장전략', '통합·다각화 전략', '경쟁기업을 인수·합병하는 것은 수평적 통합에 해당한다. 수직적 통합은 공급자나 유통업자처럼 가치사슬의 전후방 단계로 확장하는 전략이므로 ②가 옳지 않다.', '검수대기'),
(1, 4, '확장된 마케팅 믹스(7Ps)에 대한 설명으로 옳지 않은 것은?', '["프로세스(Process)는 서비스의 운영 및 전달 시스템으로서 고객의 경험과 가치를 다룬다.", "물리적 증거(Physical Evidence)는 서비스가 전달되고, 기업과 고객이 접촉하는 환경을 의미한다.", "프리미엄(Premium)은 차별화된 마케팅 전략으로서 서비스의 가치와 품격을 높이는 전략을 의미한다.", "사람(People)은 서비스의 전달 과정에서 구매자의 인식에 영향을 주는 행위자를 의미한다."]'::jsonb, 3, '마케팅', '서비스마케팅', '7P', '서비스 마케팅의 7P는 Product, Price, Place, Promotion에 People, Process, Physical Evidence를 더한 것이다. Premium은 7P의 구성요소가 아니다.', '검수대기'),
(1, 5, '임금관리에 대한 설명으로 옳지 않은 것은?', '["직무급은 직무평가로 도출된 각 직무의 상대적 가치에 따라 임금을 결정하는 방식이다.", "직능급은 종업원의 직무수행능력에 상응하도록 임금을 결정하는 방식이다.", "임금피크제는 고용은 보장하되, 일정한 연령을 기준으로 생산성과 임금을 연계하려는 제도이다.", "동일노동 동일임금의 원칙은 연공급 제도에서 적용이 용이하다."]'::jsonb, 4, '인적자원관리', '임금관리', '임금체계', '연공급은 근속연수나 연령을 중심으로 임금이 상승하므로 동일가치 노동에 동일임금을 적용하기 어렵다. 따라서 ④가 옳지 않다.', '검수대기'),
(1, 6, '이직에 대한 설명으로 옳지 않은 것은?', '["지병으로 인한 불가피한 사직은 비자발적 이직이다.", "채용비용, 교육훈련비용과 같은 이직비용이 발생한다.", "조직 입장에서 저성과자를 교체할 수 있어 긍정적인 효과가 발생한다.", "신규인력이 조직에 새로운 아이디어를 제공할 수 있어 조직 활성화의 계기를 마련할 수 있다."]'::jsonb, 1, '인적자원관리', '이직관리', '자발적·비자발적 이직', '사직은 일반적으로 근로자의 의사에 의해 고용관계가 종료되는 자발적 이직으로 분류한다. 지병으로 불가피하게 사직하더라도 해고나 정리해고와 같은 비자발적 이직으로 보지는 않는다.', '검수대기'),
(1, 7, '듀퐁 항등식(DuPont Identity)에 의한 자기자본순이익률(ROE)의 구성요소가 아닌 것은?', '["매출액순이익률", "총자산회전율", "유동비율", "자기자본승수"]'::jsonb, 3, '재무관리', '재무비율분석', '듀퐁 항등식', '듀퐁식 ROE는 매출액순이익률 × 총자산회전율 × 자기자본승수로 분해한다. 유동비율은 단기지급능력을 나타내는 유동성비율이다.', '검수대기'),
(1, 8, '경제적 주문량 모형(Economic Order Quantity)에 대한 설명으로 옳지 않은 것은?', '["연간 재고유지비용은 주문량에 반비례한다.", "제품은 주문과 동시에 도착한다.", "주문비용은 주문량에 상관없이 일정하다.", "연간 재고유지비용에는 반드시 자본비용이 포함되어야 한다."]'::jsonb, 1, '생산관리', '재고관리', 'EOQ', '기본 EOQ에서 평균재고는 Q/2이므로 연간 재고유지비용은 주문량 Q에 비례한다. 반면 연간 주문비용은 주문량이 커질수록 주문횟수가 줄어 감소한다.', '검수대기'),
(1, 9, '식스시그마의 성공적 수행을 위한 5단계 활동을 순서대로 바르게 나열한 것은?', '["(가)정의 → (나)측정 → (라)분석 → (다)개선 → (마)통제", "(가)정의 → (다)개선 → (나)측정 → (마)통제 → (라)분석", "(나)측정 → (가)정의 → (다)개선 → (라)분석 → (마)통제", "(나)측정 → (다)개선 → (가)정의 → (마)통제 → (라)분석"]'::jsonb, 1, '생산관리', '품질관리', '식스시그마 DMAIC', '식스시그마의 대표적 개선 절차는 DMAIC, 즉 Define → Measure → Analyze → Improve → Control 순서다.', '검수대기'),
(1, 10, '균형성과표(BSC)의 성과를 구성하는 네 가지 관점에 해당하지 않는 것은?', '["재무 관점", "전략 관점", "고객 관점", "학습과 성장 관점"]'::jsonb, 2, '경영전략', '성과관리', '균형성과표(BSC)', 'BSC의 네 관점은 재무, 고객, 내부 프로세스, 학습과 성장이다. ''전략 관점''은 네 가지 기본 관점에 포함되지 않는다.', '검수대기'),
(1, 11, '기업이 수행하는 활동을 캐롤(A. B. Carroll)이 제시한 기업의 사회적 책임 수준에 따라 낮은 단계부터 높은 단계까지 순서대로 바르게 나열한 것은?', '["(가)법적 책임 → (나)자선적 책임 → (다)경제적 책임 → (라)윤리적 책임", "(가)법적 책임 → (다)경제적 책임 → (나)자선적 책임 → (라)윤리적 책임", "(다)경제적 책임 → (가)법적 책임 → (라)윤리적 책임 → (나)자선적 책임", "(다)경제적 책임 → (라)윤리적 책임 → (가)법적 책임 → (나)자선적 책임"]'::jsonb, 3, '경영학원론', '기업의 사회적 책임', '캐롤 CSR 피라미드', '캐롤의 CSR 단계는 경제적 책임 → 법적 책임 → 윤리적 책임 → 자선적 책임의 순서로 설명된다.', '검수대기'),
(1, 12, '직무관리에 대한 설명으로 옳은 것은?', '["직무분석의 결과물에는 직무기술서와 직무명세서가 있다.", "직무평가 방법에는 서열법, 분류법, 점수법, 중요사건법이 있다.", "직무기술서에는 해당 직무수행에 필요한 지식, 기술, 역량 등의 상세 요건이 포함된다.", "직무평가는 직무급 확립의 기초사항으로 직무의 절대적 가치를 체계적으로 결정하는 과정이다."]'::jsonb, 1, '인적자원관리', '직무관리', '직무분석·직무평가', '직무분석의 대표적 산출물은 직무 자체의 내용과 책임을 적는 직무기술서와 수행자에게 요구되는 자격요건을 적는 직무명세서다.', '검수대기'),
(1, 13, '제품수명주기(Product Life Cycle)에 대한 설명으로 옳지 않은 것은?', '["도입기에는 시험사용을 유도하기 위해 적극적인 판매촉진이 시행된다.", "성장기의 마케팅 목표는 시장점유율의 확대이다.", "성숙기에는 경쟁자가 본격적으로 나타나며 시장 규모가 급속히 확대된다.", "쇠퇴기에는 마케팅 비용을 줄이고 수확전략을 취한다."]'::jsonb, 3, '마케팅', '제품관리', '제품수명주기(PLC)', '경쟁자의 본격적 진입과 시장의 급속한 확대는 주로 성장기의 특징이다. 성숙기에는 시장성장률이 둔화되고 경쟁이 심화된다.', '검수대기'),
(1, 14, '화폐의 시간적 가치를 고려하지 않는 투자평가 방법은?', '["수익성지수법(PI)", "순현재가치법(NPV)", "내부수익률법(IRR)", "평균회계이익률법(AAR)"]'::jsonb, 4, '재무관리', '자본예산', '투자안 평가기법', 'PI, NPV, IRR은 현금흐름을 할인하므로 화폐의 시간가치를 고려한다. AAR은 회계이익과 장부가치를 이용하는 방법으로 시간가치를 직접 반영하지 않는다.', '검수대기'),
(1, 15, '자재소요계획(MRP)의 구성요소가 아닌 것은?', '["재고 기록(IR)", "일일 작업배정표(DDL)", "자재명세서(BOM)", "주일정계획(MPS)"]'::jsonb, 2, '생산관리', '생산계획', 'MRP', 'MRP의 핵심 입력자료는 주일정계획(MPS), 자재명세서(BOM), 재고기록(IR)이다. 일일 작업배정표는 기본 구성요소가 아니다.', '검수대기'),
(1, 16, 'A 주식회사의 자기자본과 타인자본 비율은 3:1이다. 법인세율은 20%이고 자기자본비용은 12%이며 가중평균자본비용(WACC)은 12%일 때, 세전타인자본비용은?', '["8%", "10%", "12%", "15%"]'::jsonb, 4, '재무관리', '자본비용', 'WACC', '자기자본가중치 0.75, 타인자본가중치 0.25이다. 0.12 = 0.75×0.12 + 0.25×Kd×(1-0.20)이므로 Kd=0.15, 즉 15%다.', '검수대기'),
(1, 17, 'ABC 재고관리법에 대한 설명으로 옳지 않은 것은?', '["파레토의 법칙을 적용한 재고관리법이다.", "A그룹의 품목 수가 가장 많다.", "총가치 대비 비중은 C그룹 품목이 가장 낮다.", "C그룹 품목에 대한 통제가 가장 약하다."]'::jsonb, 2, '생산관리', '재고관리', 'ABC 재고관리', 'ABC 분석에서 A품목은 품목 수는 적지만 금액 비중이 크므로 가장 엄격하게 관리한다. 따라서 ''A그룹의 품목 수가 가장 많다''는 설명이 옳지 않다.', '검수대기'),
(1, 18, '의사결정 과정에서 나타나는 오류에 대한 설명으로 옳지 않은 것은?', '["고착 오류(anchoring bias): 초기 정보에 집착하여 후속 정보에 관심을 기울이지 못하는 경향", "확증 오류(confirmation bias): 자신의 관점에 합하는 정보는 쉽게 받아들이지만 반하는 정보는 무시하거나 비판적인 경향", "사후확신 오류(hindsight bias): 현재의 신념으로 미래 상황에 대해서 확신하려는 경향", "몰입의 상승(escalation of commitment): 과거의 의사결정이 잘못되었다는 확실한 증거가 있음에도 그 결과를 유지하려는 경향"]'::jsonb, 3, '조직행동', '의사결정', '의사결정 편향', '사후확신 오류는 결과를 알고 난 뒤 그 결과를 사전에 예측할 수 있었던 것처럼 생각하는 경향이다. 미래를 현재 신념으로 확신하는 설명과는 다르다.', '검수대기'),
(1, 19, '전사적 품질경영(TQM)에 대한 설명으로 옳지 않은 것은?', '["생산 프로세스에 관련된 모든 요소를 지속적으로 개선하는 것이다.", "전사적 프로세스와 데이터 관리 필요사항을 지원하는 대규모 통합 정보 시스템이다.", "조직 내 모든 구성원의 참여가 있어야 한다.", "고객만족을 목표로 하며 품질은 고객의 기대를 충족하는 정도로 정의된다."]'::jsonb, 2, '생산관리', '품질관리', 'TQM', 'TQM은 전사적 참여와 지속적 개선을 통한 품질경영 철학이다. 대규모 통합 정보시스템에 대한 설명은 ERP에 가깝다.', '검수대기'),
(1, 20, '소비자 의사결정에 대한 설명으로 옳지 않은 것은?', '["소비자가 대안을 비교ㆍ평가하는 데 사용하는 속성과 각 속성의 중요도를 평가기준이라 한다.", "자신과 관련된 정보에 노출될 때마다 상당한 주의를 기울이는 것을 강화된 주의(heightened attention)라 한다.", "분리식(disjunctive rule)은 소비자가 중요하게 여기는 각 속성의 평가점수가 최소 어느 정도는 되어야 한다는 수용기준을 설정하고, 그 속성에서 수용기준을 만족시키지 못하는 상표를 제거해 가는 방식이다.", "구매 후 부조화의 감소 방안에는 자신이 선택한 대안의 장점을 의도적으로 강화하고 단점을 축소하는 방법이 있다."]'::jsonb, 3, '마케팅', '소비자행동', '대안평가 규칙', '각 속성에 최소 수용기준을 설정하고 하나라도 기준에 미달하면 제거하는 방식은 결합식(conjunctive rule)에 해당한다. 분리식은 중요한 속성 중 하나 이상이 높은 기준을 충족하면 선택하는 방식이다.', '검수대기'),
(1, 21, '자본자산가격결정모형(CAPM)에 대한 설명으로 옳은 것은?', '["포트폴리오의 구성자산 수가 증가할수록 포트폴리오의 위험은 증가한다.", "위험자산의 수익률은 위험수익률에 위험프리미엄을 합한 값으로 결정된다.", "증권시장선(SML)은 체계적 위험과 기대수익률의 관계를 설명할 수 있다.", "동질적 기대의 가정이 성립하는 완전자본시장에서의 모든 투자자들은 분산투자를 통해 체계적 위험을 제거할 수 있다."]'::jsonb, 3, '재무관리', '위험과 수익', 'CAPM·SML', 'SML은 베타로 측정되는 체계적 위험과 기대수익률의 관계를 나타낸다. 분산투자로 제거할 수 있는 것은 비체계적 위험이다.', '검수대기'),
(1, 22, '목표관리(MBO)에 대한 설명으로 옳지 않은 것은?', '["목표는 구체적이어야 한다.", "맥그리거의 X이론에 바탕을 둔다.", "목표 달성 여부에 대한 피드백을 제공한다.", "목표 설정 시 구성원이 참여한다."]'::jsonb, 2, '조직행동', '동기부여·성과관리', 'MBO', 'MBO는 구성원의 참여, 구체적 목표 설정, 피드백 등을 강조하며 자율적·자기통제적 인간관과 관련된다. X이론을 기반으로 한다는 설명은 부적절하다.', '검수대기'),
(1, 23, '서비스품질을 측정하기 위해 개발된 SERVQUAL의 핵심 요소에 대한 설명으로 옳지 않은 것은?', '["유형성(tangibles): 물리적 시설, 장비, 커뮤니케이션, 직원의 외형", "공감성(empathy): 고객에게 개인적이며 자상한 주의를 제공하는 정도", "반응성(responsiveness): 고객을 돕고 신속한 서비스를 제공하려는 태도", "확신성(assurance): 약속한 서비스를 믿을 수 있고 정확하게 수행할 수 있는 능력"]'::jsonb, 4, '마케팅', '서비스마케팅', 'SERVQUAL', '약속한 서비스를 믿을 수 있고 정확하게 수행하는 능력은 신뢰성(reliability)이다. 확신성(assurance)은 직원의 지식·예절과 고객에게 신뢰와 확신을 주는 능력을 뜻한다.', '검수대기'),
(1, 24, '민츠버그(H. Mintzberg)가 제시한 경영자의 역할에 대한 설명으로 옳지 않은 것은?', '["문제해결자(disturbance handler)는 파업이 임박한 경우, 적극적으로 개입한다.", "감시자(monitor)는 비정상적인 회사 운영을 다양한 방법으로 조정한다.", "정보확산자(disseminator)는 자신의 개인 네트워크로 수집한 정보를 회사의 구성원에게 전달한다.", "대변자(spokesperson)는 회사의 계획, 정책, 활동 등을 외부에 공개한다."]'::jsonb, 2, '경영학원론', '경영자 역할', '민츠버그 경영자 역할', '감시자(monitor)는 조직 내외의 정보를 탐색·수집하는 정보적 역할이다. 비정상적 운영을 조정하는 것은 문제해결자 역할에 가깝다.', '검수대기'),
(1, 25, '포터(M. Porter)의 산업구조분석 모형을 근거로 할 때, 수익률이 가장 높은 경우는?', '["공급자 교섭력 낮음 / 구매자 교섭력 높음 / 대체재의 위협 낮음 / 진입장벽 낮음", "공급자 교섭력 높음 / 구매자 교섭력 낮음 / 대체재의 위협 높음 / 진입장벽 높음", "공급자 교섭력 높음 / 구매자 교섭력 높음 / 대체재의 위협 높음 / 진입장벽 낮음", "공급자 교섭력 낮음 / 구매자 교섭력 낮음 / 대체재의 위협 낮음 / 진입장벽 높음"]'::jsonb, 4, '경영전략', '산업구조분석', '포터 5 Forces', '산업의 수익성은 공급자·구매자의 교섭력이 낮고, 대체재 위협이 낮으며, 진입장벽이 높을수록 유리하다. 네 조건을 모두 충족하는 ④가 가장 적합하다.', '검수대기')
on conflict(set_id,question_no) do update set stem=excluded.stem, choices=excluded.choices, correct_answer=excluded.correct_answer, major_category=excluded.major_category, mid_category=excluded.mid_category, topic=excluded.topic, explanation=excluded.explanation, review_status=excluded.review_status;
